import click
from click.testing import CliRunner
r = CliRunner()

def mk(kind):
    if kind == "boolflag":
        @click.command()
        @click.option("--flag", is_flag=True)
        def c(flag): return flag
    elif kind == "pair":
        @click.command()
        @click.option("--flag/--no-flag")
        def c(flag): return flag
    elif kind == "group":
        @click.command()
        @click.option("--upper", "t", flag_value="upper")
        @click.option("--lower", "t", flag_value="lower")
        def c(t): return t
    elif kind == "count":
        @click.command()
        @click.option("-v", count=True)
        def c(v): return v
    elif kind == "multiflag":
        @click.command()
        @click.option("--flag", is_flag=True, multiple=True)
        def c(flag): return flag
    return c

for kind in ["boolflag","pair","group","count","multiflag"]:
    cmd = mk(kind)
    name = {"group":"t"}.get(kind, "v" if kind=="count" else "flag")
    for dmval in [True, False, "1", "0", "upper", "lower", (), [True], None]:
        res = r.invoke(cmd, [], default_map={name: dmval}, standalone_mode=False)
        print(f"{kind:10} dm={dmval!r:8} -> {res.return_value!r} {res.exception!r}")
